export async function getEntityTrace(entityType: string, entityId: string) {
  const filters: TransactionFilters = { entity_type: entityType, entity_id: entityId };
  return getTransactionsPaginated(filters);
}

export async function getWithdrawals(
  filters: { status?: string; limit?: number } = {},
  cursor?: { created_at: string; id: string }
) {
  await requireAdminRole(['support', 'moderator', 'admin', 'super_admin']);
  const supabase = await supabaseServer();
  
  let query = supabase
    .from('withdrawal_requests')
    .select('*')
    .order('created_at', { ascending: false })
    .order('id', { ascending: false });

  if (filters.status) query = query.eq('status', filters.status);
  
  if (cursor) {
    query = query.or(`created_at.lt.${cursor.created_at},and(created_at.eq.${cursor.created_at},id.lt.${cursor.id})`);
  }
  
  const limit = filters.limit || 50;
  const { data, error } = await query.limit(limit);

  if (error) throw new Error('Query failed');

  const nextCursor = data.length === limit ? {
    created_at: data[data.length - 1].created_at,
    id: data[data.length - 1].id
  } : undefined;

  return { data, nextCursor };
}

